  const options = { weekday: 'short', month: 'short', day: 'numeric' };
  return date.toLocaleDateString('en-US', options);
}

// Helper: Calculate and format week-over-week change
function calculateWOWChange(current, previous) {
  return {
    leads: previous.leads === 0 ? 0 : ((current.leads - previous.leads) / previous.leads) * 100,
    conversions: previous.conversions === 0 ? 0 : ((current.conversions - previous.conversions) / previous.conversions) * 100,
    revenue: previous.revenue === 0 ? 0 : ((current.revenue - previous.revenue) / previous.revenue) * 100
  };
}

// Helper: Format week-over-week as % with arrows
function formatWOW(change) {
  const sign = change >= 0 ? "▲" : "▼";
  return sign + " " + Math.abs(change.toFixed(1)) + "%";
}
