function sendWeeklyKPISummary() {
  const ss = SpreadsheetApp.getActive();
  const sheet = ss.getSheetByName('Data') || ss.getActiveSheet(); // change 'Data' to your sheet name
  const tz = ss.getSpreadsheetTimeZone(); // best to match the sheet timezone

  const values = sheet.getDataRange().getValues();
  const rows = values.slice(1); // skip headers

  // We run Monday 8am; we want the last completed week (Mon–Sun)
  const today = new Date();
  const thisWeekMon = startOfWeekMonday_(today, tz); // Monday of current week
  const reportStart = addDays_(thisWeekMon, -7);     // last week's Monday
  const reportEnd   = addDays_(thisWeekMon, -1);     // last week's Sunday

  const prevStart = addDays_(reportStart, -7);
  const prevEnd   = addDays_(reportEnd, -7);

  const reportTotals = getTotalsInRange_(rows, reportStart, reportEnd, tz);
  const prevTotals   = getTotalsInRange_(rows, prevStart, prevEnd, tz);

  const wow = calcWow_(reportTotals, prevTotals);

  const subject = `Weekly KPI Summary (${fmt_(reportStart, tz)} – ${fmt_(reportEnd, tz)})`;
  const htmlBody = buildHtml_(reportTotals, wow, reportStart, reportEnd, tz);

  const recipients = [
    "email1@example.com",
    "email2@example.com",
    "email3@example.com",
    "email4@example.com",
    "email5@example.com",
    "email6@example.com"
  ].join(",");

  MailApp.sendEmail({ to: recipients, subject, htmlBody });
}

function getTotalsInRange_(rows, startDate, endDate, tz) {
  const startKey = dateKey_(startDate, tz);
  const endKey   = dateKey_(endDate, tz);

  const totals = { leads: 0, conversions: 0, revenue: 0 };

  for (const r of rows) {
    const d = r[0];
    if (!(d instanceof Date)) continue;

    const key = dateKey_(d, tz);
    if (key < startKey || key > endKey) continue;

    totals.leads += Number(r[2]) || 0;
    totals.conversions += Number(r[3]) || 0;
    totals.revenue += Number(r[4]) || 0;
  }
  return totals;
}

function calcWow_(cur, prev) {
  return {
    leads: pctChange_(cur.leads, prev.leads),
    conversions: pctChange_(cur.conversions, prev.conversions),
    revenue: pctChange_(cur.revenue, prev.revenue),
  };
}

function pctChange_(cur, prev) {
  if (!prev) return null; // avoid divide-by-zero; show N/A
  return ((cur - prev) / prev) * 100;
}

function buildHtml_(totals, wow, startDate, endDate, tz) {
  const wowCell = (v) => {
    if (v === null) return 'N/A';
    const arrow = v >= 0 ? '▲' : '▼';
    return `${arrow} ${Math.abs(v).toFixed(1)}%`;
  };

  const money = (n) => n.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  return `
  <div style="font-family: Arial, sans-serif">
    <h3 style="margin:0 0 8px 0">Weekly KPI Summary</h3>
    <div style="margin:0 0 12px 0;color:#444">
      ${fmt_(startDate, tz)} – ${fmt_(endDate, tz)}
    </div>

    <table border="1" cellpadding="8" style="border-collapse:collapse;min-width:520px">
      <tr style="background:#f3f3f3">
        <th align="left">KPI</th>
        <th align="right">Total</th>
        <th align="right">WoW</th>
      </tr>
      <tr>
        <td>Leads</td>
        <td align="right">${totals.leads.toLocaleString()}</td>
        <td align="right">${wowCell(wow.leads)}</td>
      </tr>
      <tr>
        <td>Conversions</td>
        <td align="right">${totals.conversions.toLocaleString()}</td>
        <td align="right">${wowCell(wow.conversions)}</td>
      </tr>
      <tr>
        <td>Revenue</td>
        <td align="right">${money(totals.revenue)}</td>
        <td align="right">${wowCell(wow.revenue)}</td>
      </tr>
    </table>
  </div>`;
}

/** Monday start-of-week in the given timezone */
function startOfWeekMonday_(date, tz) {
  // Use timezone key to avoid DST weirdness
  const ymd = Utilities.formatDate(date, tz, "yyyy-MM-dd");
  const local = new Date(ymd + "T00:00:00"); // local-midnight-ish anchor
  const day = Number(Utilities.formatDate(date, tz, "u")); // 1=Mon ... 7=Sun
  return addDays_(local, -(day - 1));
}

function addDays_(date, days) {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

function dateKey_(date, tz) {
  return Utilities.formatDate(date, tz, "yyyyMMdd"); // string compares correctly
}

function fmt_(date, tz) {
  return Utilities.formatDate(date, tz, "MMM d, yyyy");
}
```

