```javascript
function sendWeeklyKPISummary() {
  const ss = SpreadsheetApp.getActive();
  const tz = ss.getSpreadsheetTimeZone();

  const dataSheet = ss.getSheetByName("KPI_Data");
  if (!dataSheet) throw new Error('Sheet "KPI_Data" not found.');

  const recipients = getRecipients_(ss, "Recipients", "A2:A");
  if (!recipients.length) throw new Error('No recipients found in Recipients!A2:A');

  const values = dataSheet.getDataRange().getValues();
  if (values.length < 2) throw new Error("No data rows found.");

  const rows = values.slice(1); // skip header row

  // Report = last completed Mon–Sun
  const today = new Date();
  const thisWeekMon = startOfWeekMonday_(today, tz); // Monday of current week
  const reportStart = addDays_(thisWeekMon, -7);     // last Monday
  const reportEnd = addDays_(thisWeekMon, -1);       // last Sunday

  // Comparison week = week before report week
  const prevStart = addDays_(reportStart, -7);
  const prevEnd = addDays_(reportEnd, -7);

  const reportTotals = getTotalsInRange_(rows, reportStart, reportEnd, tz);
  const prevTotals = getTotalsInRange_(rows, prevStart, prevEnd, tz);
  const wowTotals = calcWow_(reportTotals, prevTotals);

  const bySource = getTotalsBySource_(rows, reportStart, reportEnd, tz);

  const subject = `Weekly KPI Summary (${fmt_(reportStart, tz)} – ${fmt_(reportEnd, tz)})`;
  const htmlBody = buildHtml_(reportTotals, wowTotals, bySource, reportStart, reportEnd, tz);

  MailApp.sendEmail({
    to: recipients.join(","),
    subject,
    htmlBody,
  });
}

/** Reads recipient emails from a single column range, e.g. Recipients!A2:A */
function getRecipients_(ss, tabName, a1Range) {
  const sh = ss.getSheetByName(tabName);
  if (!sh) throw new Error(`Config sheet "${tabName}" not found.`);

  const vals = sh.getRange(a1Range).getValues().flat();
  const emails = vals
    .map(v => String(v || "").trim())
    .filter(v => v && v.includes("@"));

  // de-dupe
  return [...new Set(emails)];
}

/** Totals across all sources for a date range (inclusive, by local date key). */
function getTotalsInRange_(rows, startDate, endDate, tz) {
  const startKey = dateKey_(startDate, tz);
  const endKey = dateKey_(endDate, tz);

  const totals = { leads: 0, conversions: 0, revenue: 0 };

  for (const r of rows) {
    const d = r[0];
    if (!(d instanceof Date)) continue;

    const key = dateKey_(d, tz);
    if (key < startKey || key > endKey) continue;

    totals.leads += Number(r[2]) || 0;        // C
    totals.conversions += Number(r[3]) || 0;  // D
    totals.revenue += Number(r[4]) || 0;      // E
  }
  return totals;
}

/** Totals grouped by Source for a date range (inclusive). */
function getTotalsBySource_(rows, startDate, endDate, tz) {
  const startKey = dateKey_(startDate, tz);
  const endKey = dateKey_(endDate, tz);

  /** @type {Object.<string, {leads:number, conversions:number, revenue:number}>} */
  const map = {};

  for (const r of rows) {
    const d = r[0];
    if (!(d instanceof Date)) continue;

    const key = dateKey_(d, tz);
    if (key < startKey || key > endKey) continue;

    const source = String(r[1] || "Unattributed").trim() || "Unattributed"; // B

    if (!map[source]) map[source] = { leads: 0, conversions: 0, revenue: 0 };
    map[source].leads += Number(r[2]) || 0;
    map[source].conversions += Number(r[3]) || 0;
    map[source].revenue += Number(r[4]) || 0;
  }

  // Convert to array and sort by revenue desc (then leads desc)
  const arr = Object.entries(map).map(([source, totals]) => ({ source, ...totals }));
  arr.sort((a, b) => (b.revenue - a.revenue) || (b.leads - a.leads));
  return arr;
}

function calcWow_(cur, prev) {
  return {
    leads: pctChange_(cur.leads, prev.leads),
    conversions: pctChange_(cur.conversions, prev.conversions),
    revenue: pctChange_(cur.revenue, prev.revenue),
  };
}

function pctChange_(cur, prev) {
  if (!prev) return null; // show N/A if previous week is 0
  return ((cur - prev) / prev) * 100;
}

function buildHtml_(totals, wow, bySource, startDate, endDate, tz) {
  const wowCell = (v) => {
    if (v === null) return "N/A";
    const arrow = v >= 0 ? "▲" : "▼";
    return `${arrow} ${Math.abs(v).toFixed(1)}%`;
  };

  const money = (n) =>
    n.toLocaleString("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

  const pct = (n) => (isFinite(n) ? (n * 100).toFixed(1) + "%" : "—");

  const totalRevenue = totals.revenue || 0;
  const totalLeads = totals.leads || 0;

  const sourceRowsHtml = bySource.length
    ? bySource.map(s => {
        const revenueShare = totalRevenue ? (s.revenue / totalRevenue) : NaN;
        const leadsShare = totalLeads ? (s.leads / totalLeads) : NaN;
        return `
          <tr>
            <td>${escapeHtml_(s.source)}</td>
            <td align="right">${(s.leads || 0).toLocaleString()}</td>
            <td align="right">${(s.conversions || 0).toLocaleString()}</td>
            <td align="right">${money(s.revenue || 0)}</td>
            <td align="right">${pct(revenueShare)}</td>
            <td align="right">${pct(leadsShare)}</td>
          </tr>`;
      }).join("")
    : `<tr><td colspan="6" style="color:#666">No rows found for this week.</td></tr>`;

  return `
  <div style="font-family: Arial, sans-serif; line-height:1.35">
    <h3 style="margin:0 0 6px 0">Weekly KPI Summary</h3>
    <div style="margin:0 0 12px 0;color:#444">
      ${fmt_(startDate, tz)} – ${fmt_(endDate, tz)}
    </div>

    <table border="1" cellpadding="8" style="border-collapse:collapse;min-width:560px;margin-bottom:14px">
      <tr style="background:#f3f3f3">
        <th align="left">KPI</th>
        <th align="right">Total</th>
        <th align="right">WoW</th>
      </tr>
      <tr>
        <td>Leads</td>
        <td align="right">${totals.leads.toLocaleString()}</td>
        <td align="right">${wowCell(wow.leads)}</td>
      </tr>
      <tr>
        <td>Conversions</td>
        <td align="right">${totals.conversions.toLocaleString()}</td>
        <td align="right">${wowCell(wow.conversions)}</td>
      </tr>
      <tr>
        <td>Revenue</td>
        <td align="right">${money(totals.revenue)}</td>
        <td align="right">${wowCell(wow.revenue)}</td>
      </tr>
    </table>

    <div style="font-weight:bold;margin:0 0 6px 0">By Source</div>
    <table border="1" cellpadding="8" style="border-collapse:collapse;min-width:760px">
      <tr style="background:#f3f3f3">
        <th align="left">Source</th>
        <th align="right">Leads</th>
        <th align="right">Conversions</th>
        <th align="right">Revenue</th>
        <th align="right">% of Revenue</th>
        <th align="right">% of Leads</th>
      </tr>
      ${sourceRowsHtml}
    </table>
  </div>`;
}

/** Monday start-of-week in the given timezone */
function startOfWeekMonday_(date, tz) {
  const ymd = Utilities.formatDate(date, tz, "yyyy-MM-dd");
  const localMidnightAnchor = new Date(ymd + "T00:00:00");
  const day = Number(Utilities.formatDate(date, tz, "u")); // 1=Mon ... 7=Sun
  return addDays_(localMidnightAnchor, -(day - 1));
}

function addDays_(date, days) {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

function dateKey_(date, tz) {
  return Utilities.formatDate(date, tz, "yyyyMMdd"); // safe inclusive compare
