            <td align="right">${(s.conversions || 0).toLocaleString()}</td>
            <td align="right">${money(s.revenue || 0)}</td>
            <td align="right">${pct(revenueShare)}</td>
            <td align="right">${pct(leadsShare)}</td>
          </tr>`;
      }).join("")
    : `<tr><td colspan="6" style="color:#666">No rows found for this week.</td></tr>`;

  return `
