      ${fmt_(startDate, tz)} – ${fmt_(endDate, tz)}
    </div>

    <table border="1" cellpadding="8" style="border-collapse:collapse;min-width:560px;margin-bottom:14px">
      <tr style="background:#f3f3f3">
        <th align="left">KPI</th>
        <th align="right">Total</th>
        <th align="right">WoW</th>
      </tr>
      <tr>
        <td>Leads</td>
        <td align="right">${totals.leads.toLocaleString()}</td>
        <td align="right">${wowCell(wow.leads)}</td>
      </tr>
      <tr>
        <td>Conversions</td>
        <td align="right">${totals.conversions.toLocaleString()}</td>
        <td align="right">${wowCell(wow.conversions)}</td>
      </tr>
      <tr>
        <td>Revenue</td>
        <td align="right">${money(totals.revenue)}</td>
        <td align="right">${wowCell(wow.revenue)}</td>
      </tr>
    </table>

    <div style="font-weight:bold;margin:0 0 6px 0">By Source</div>
    <table border="1" cellpadding="8" style="border-collapse:collapse;min-width:760px">
      <tr style="background:#f3f3f3">
