  if (values.length < 2) throw new Error("No data rows found.");

  const rows = values.slice(1); // skip header row

  // Report = last completed Mon–Sun
  const today = new Date();
  const thisWeekMon = startOfWeekMonday_(today, tz); // Monday of current week
  const reportStart = addDays_(thisWeekMon, -7);     // last Monday
  const reportEnd = addDays_(thisWeekMon, -1);       // last Sunday

  // Comparison week = week before report week
  const prevStart = addDays_(reportStart, -7);
  const prevEnd = addDays_(reportEnd, -7);

  const reportTotals = getTotalsInRange_(rows, reportStart, reportEnd, tz);
  const prevTotals = getTotalsInRange_(rows, prevStart, prevEnd, tz);
  const wowTotals = calcWow_(reportTotals, prevTotals);

  // Log this run (always, for audit trail)
  logRun_(ss, tz, reportStart, reportEnd, reportTotals, wowTotals);

  // Only email if at least one row in the report week
  if (reportTotals.rowCount === 0) return;

  const bySource = getTotalsBySource_(rows, reportStart, reportEnd, tz);
  const bySourcePrev = getTotalsBySource_(rows, prevStart, prevEnd, tz);

  const subject = `Weekly KPI Summary (${fmt_(reportStart, tz)} – ${fmt_(reportEnd, tz)})`;
  const htmlBody = buildHtml_(reportTotals, wowTotals, bySource, bySourcePrev, reportStart, reportEnd, tz);

  MailApp.sendEmail({
    to: recipients.join(","),
    subject,
    htmlBody,
  });
}
```

---

## ✅ What Changed?

| Function | Before | After |
|---------|--------|-------|
| `getTotalsInRange_()` | Only returned totals | Now also returns `rowCount` (number of rows processed) |
| `countRowsInRange_()` | Needed to count rows in a second pass | Removed — redundant logic gone |
| `sendWeeklyKPISummary()` | Checked for row count via a second function | Now uses `reportTotals.rowCount` from same pass |

---

## ✅ Result

- **Performance**: Single-pass over the data — better for **large datasets**
- **Clarity**: No extra functions needed — fewer moving parts
- **Future-proof**: Easy to add more row-based metrics later

---

