This is the **Express server** that reads your `.md` files from the `notes` directory and provides the required endpoints.

```js
const express = require('express');
const fs = require('fs').promises;
const path = require('path');
const marked = require('marked');

const app = express();
const PORT = process.env.PORT || 3000;
const NOTES_DIR = path.join(__dirname, 'notes');

// Utility to parse a markdown file into title, date, slug, and content
async function parseNote(filePath) {
  const content = await fs.readFile(filePath, 'utf-8');
  const lines = content.trim().split('\n');
  const title = lines[0].startsWith('# ') ? lines[0].slice(2).trim() : 'Untitled';
  const date = path.basename(filePath).split('-').slice(0, 3).join('-');
  const slug = path.basename(filePath).replace(/\.md$/, '').split('-').slice(3).join('-');

  return {
    title,
    date,
    slug,
    content,
    html: marked.parse(content)
  };
}

// GET /api/notes
app.get('/api/notes', async (req, res) => {
  try {
    const files = await fs.readdir(NOTES_DIR);
    const markdownFiles = files.filter(file => file.endsWith('.md'));

    const notesPromises = markdownFiles.map(file => {
      const filePath = path.join(NOTES_DIR, file);
      return parseNote(filePath);
    });

    const notes = await Promise.all(notesPromises);
    res.json(notes.map(n => ({ title: n.title, date: n.date, slug: n.slug })));
  } catch (err) {
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// GET /api/notes/:slug
app.get('/api/notes/:slug', async (req, res) => {
  try {
    const files = await fs.readdir(NOTES_DIR);
    const markdownFiles = files.filter(file => file.endsWith('.md'));

    const matchingFile = markdownFiles.find(file => {
      const slug = file.replace(/\.md$/, '').split('-').slice(3).join('-');
      return slug === req.params.slug;
    });

    if (!matchingFile) {
      return res.status(404).json({ error: 'Note not found' });
    }

    const filePath = path.join(NOTES_DIR, matchingFile);
    const note = await parseNote(filePath);
    res.json({
      title: note.title,
      date: note.date,
      slug: note.slug,
      content: note.html
    });
  } catch (err) {
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

app.listen(PORT, () => {
  console.log(`Release Notes API running on http://localhost:${PORT}`);
});
```

---

## 🛡️ **Safety Considerations**

- 🚫 No path traversal: we only read from the `notes/` folder and do **not** let the user input directly affect the file system path.
- 🧹 Clean file name parsing: only `.md` files are considered, and we extract the slug from the file name to prevent injection.

