const express = require("express");
const fsp = require("fs").promises;
const path = require("path");

const app = express();
const PORT = process.env.PORT || 3000;
const NOTES_DIR = path.join(__dirname, "notes");

// Only accept filenames like: 2025-01-01-my-title.md
const FILENAME_RE = /^(\d{4}-\d{2}-\d{2})-(.+)\.md$/;

// In-memory index: slug -> { filePath, date, title }
let indexBySlug = new Map();
let listCache = []; // [{slug,date,title}]
let lastIndexedAt = 0;

async function extractTitleFromMarkdown(md) {
  // First H1: "# Title"
  const lines = md.split(/\r?\n/);
  for (const line of lines) {
    const m = line.match(/^#\s+(.+)\s*$/);
    if (m) return m[1].trim();
  }
  return "Untitled";
}

async function buildIndex() {
  const entries = await fsp.readdir(NOTES_DIR, { withFileTypes: true });

  const nextIndex = new Map();
  const nextList = [];

  for (const ent of entries) {
    if (!ent.isFile()) continue;

    const m = ent.name.match(FILENAME_RE);
    if (!m) continue;

    const date = m[1];
    const slug = m[2];

    // optional: lock down slug characters (prevents weird edge cases)
    // allow letters, numbers, dash, underscore
    if (!/^[a-z0-9-_]+$/i.test(slug)) continue;

    const filePath = path.join(NOTES_DIR, ent.name);

    // Read just once during indexing to get title (fast enough for 200 files)
    const md = await fsp.readFile(filePath, "utf8");
    const title = await extractTitleFromMarkdown(md);

    nextIndex.set(slug, { filePath, date, title });
    nextList.push({ slug, date, title });
  }

  // sort newest first (string sort works for YYYY-MM-DD)
  nextList.sort((a, b) => b.date.localeCompare(a.date));

  indexBySlug = nextIndex;
  listCache = nextList;
  lastIndexedAt = Date.now();
  console.log(`Indexed ${listCache.length} notes`);
}

// Initial index + periodic refresh
buildIndex().catch(err => {
  console.error("Failed to build index:", err);
  process.exit(1);
});
setInterval(() => {
  buildIndex().catch(err => console.error("Reindex failed:", err));
}, 30_000);

// GET /api/notes -> list
app.get("/api/notes", (req, res) => {
  res.json({
    indexedAt: lastIndexedAt,
    notes: listCache
  });
});

// GET /api/notes/:slug -> single note markdown
app.get("/api/notes/:slug", async (req, res) => {
  const slug = req.params.slug;

  const meta = indexBySlug.get(slug);
  if (!meta) return res.status(404).json({ error: "Note not found" });

  try {
    const markdown = await fsp.readFile(meta.filePath, "utf8");
    res.json({
      slug,
      date: meta.date,
      title: meta.title,
      markdown
    });
  } catch (err) {
    res.status(500).json({ error: "Failed to read note" });
  }
});

app.listen(PORT, () => {
  console.log(`Release Notes API running on http://localhost:${PORT}`);
});
```

