```js
const express = require("express");
const fsp = require("fs").promises;
const path = require("path");

const app = express();
const PORT = process.env.PORT || 3000;
const NOTES_DIR = path.join(__dirname, "notes");

// YYYY-MM-DD-slug.md where slug is lowercase letters/numbers/dash/underscore
const FILENAME_RE = /^(\d{4}-\d{2}-\d{2})-([a-z0-9-_]+)\.md$/;

let indexBySlug = new Map();
let listCache = [];
let lastIndexedAt = 0;

function extractTitleFromMarkdown(md) {
  const lines = md.split(/\r?\n/);
  for (const line of lines) {
    const m = line.match(/^#\s+(.+)\s*$/);
    if (m) return m[1].trim();
  }
  return "Untitled";
}

async function buildIndex() {
  const entries = await fsp.readdir(NOTES_DIR, { withFileTypes: true });

  const nextIndex = new Map();
  const nextList = [];

  for (const ent of entries) {
    if (!ent.isFile()) continue;

    const m = ent.name.match(FILENAME_RE);
    if (!m) continue;

    const date = m[1];
    const slug = m[2];
    const filePath = path.join(NOTES_DIR, ent.name);

    const md = await fsp.readFile(filePath, "utf8");
    const title = extractTitleFromMarkdown(md);

    nextIndex.set(slug, { filePath, date, title });
    nextList.push({ slug, date, title });
  }

  nextList.sort((a, b) => b.date.localeCompare(a.date));

  indexBySlug = nextIndex;
  listCache = nextList;
  lastIndexedAt = Date.now();
}

