  console.error("Failed to build index:", err);
  process.exit(1);
});

setInterval(() => buildIndex().catch(err => console.error("Reindex failed:", err)), 30_000);

app.get("/health", (req, res) => {
  res.json({ status: "ok", indexedNotes: listCache.length, lastIndexedAt });
});

app.get("/api/notes", (req, res) => {
  res.json({ indexedAt: lastIndexedAt, notes: listCache });
});

app.get("/api/notes/:slug", async (req, res) => {
  const slug = req.params.slug;
  const meta = indexBySlug.get(slug);
  if (!meta) return res.status(404).json({ error: "Note not found" });

  try {
    const markdown = await fsp.readFile(meta.filePath, "utf8");
    res.json({ slug, date: meta.date, title: meta.title, markdown });
  } catch (err) {
    res.status(500).json({ error: "Failed to read note" });
  }
});

app.listen(PORT, () => console.log(`Running on http://localhost:${PORT}`));
```

