## 1) Add a tiny frontend (static files)

Create:

```
web/
  index.html
  app.js
  style.css
```

### `web/index.html`
```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Release Notes</title>
  <link rel="stylesheet" href="/style.css" />
</head>
<body>
  <div class="layout">
    <aside class="sidebar">
      <h1>Release Notes</h1>
      <div id="status" class="status">Loading…</div>
      <ul id="notes"></ul>
    </aside>

    <main class="content">
      <article>
        <h2 id="title"></h2>
        <div id="meta" class="meta"></div>
        <pre id="markdown" class="markdown"></pre>
      </article>
    </main>
  </div>

  <script src="/app.js"></script>
</body>
</html>
```

### `web/style.css`
```css
body { margin: 0; font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif; }
.layout { display: grid; grid-template-columns: 320px 1fr; height: 100vh; }
.sidebar { border-right: 1px solid #eee; padding: 16px; overflow: auto; }
.content { padding: 24px; overflow: auto; }
#notes { list-style: none; padding: 0; margin: 12px 0 0; }
#notes li { margin: 0; padding: 8px 0; border-bottom: 1px solid #f2f2f2; }
#notes a { text-decoration: none; color: #0b66c3; }
#notes a.active { font-weight: 700; }
.status { color: #666; font-size: 12px; margin-top: 6px; }
.meta { color: #666; font-size: 13px; margin: 6px 0 12px; }
.markdown { white-space: pre-wrap; background: #fafafa; padding: 12px; border-radius: 8px; border: 1px solid #eee; }
```

### `web/app.js`
```js
const $ = (id) => document.getElementById(id);

function setActive(slug) {
  document.querySelectorAll("#notes a").forEach(a => {
    a.classList.toggle("active", a.dataset.slug === slug);
  });
}

async function loadList() {
  const res = await fetch("/api/notes");
  if (!res.ok) throw new Error("Failed to load notes list");
  return res.json();
}

async function loadNote(slug) {
  const res = await fetch(`/api/notes/${encodeURIComponent(slug)}`);
  if (!res.ok) throw new Error("Failed to load note");
  return res.json();
}

function renderList(notes) {
  const ul = $("notes");
  ul.innerHTML = "";
  for (const n of notes) {
    const li = document.createElement("li");
    const a = document.createElement("a");
    a.href = `#${n.slug}`;
    a.textContent = `${n.date} — ${n.title}`;
    a.dataset.slug = n.slug;
    li.appendChild(a);
    ul.appendChild(li);
  }
}

function renderNote(note) {
  $("title").textContent = note.title;
  $("meta").textContent = `${note.date} • ${note.slug}`;
  $("markdown").textContent = note.markdown;
  setActive(note.slug);
}

async function route() {
  const slug = (location.hash || "").replace(/^#/, "");
  if (!slug) return;

  $("status").textContent = "Loading note…";
  const note = await loadNote(slug);
  renderNote(note);
  $("status").textContent = "";
}

(async function main() {
  try {
    $("status").textContent = "Loading notes…";
    const data = await loadList();
    renderList(data.notes);

    $("status").textContent = "";
    if (!location.hash && data.notes.length) {
      location.hash = `#${data.notes[0].slug}`;
    } else {
      await route();
    }
    window.addEventListener("hashchange", () => route().catch(err => $("status").textContent = err.message));
  } catch (err) {
    $("status").textContent = err.message || "Error";
  }
})();
```

## 2) Serve the static frontend via NGINX

Update your NGINX config to serve `/` from `web/`, while keeping `/api/` proxied:

```nginx
# inside the HTTPS server block

location /api/ {
  proxy_pass http://api:3000;
  proxy_set_header Host $host;
  proxy_set_header X-Real-IP $remote_addr;
  proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
  proxy_set_header X-Forwarded-Proto $scheme;
}

location / {
  root /usr/share/nginx/html;
  try_files $uri $uri/ /index.html;
}
```

## 3) Mount the web folder into the nginx container

In `docker-compose.yml` under `nginx.volumes`, add:

```yaml
- ./web:/usr/share/nginx/html:ro
```

Then:

```bash
docker compose up -d --build
```

That’ll give you:
- `https://release-notes-api.company.com/` → UI
- `https://release-notes-api.company.com/api/notes` → API

